const floor=new THREE.Mesh(new THREE.CircleGeometry(3.3,96),new THREE.MeshStandardMaterial({color:0xcfd3cd,transparent:true,opacity:.3,roughness:1})); floor.rotation.x=-Math.PI/2; floor.position.y=-1.58; floor.receiveShadow=true; scene.add(floor);
const ring=new THREE.Mesh(new THREE.RingGeometry(2.45,2.48,96),new THREE.MeshBasicMaterial({color:0x8e8aeb,transparent:true,opacity:.22,side:THREE.DoubleSide})); ring.rotation.x=-Math.PI/2; ring.position.y=-1.55; scene.add(ring);
let modelGroup=new THREE.Group(); scene.add(modelGroup);

function uniquePermutations(values){const set=new Set(); const out=[]; const perm=(a,l=0)=>{if(l===a.length){const k=a.join(',');if(!set.has(k)){set.add(k);out.push([...a])}return}for(let i=l;i<a.length;i++){[a[l],a[i]]=[a[i],a[l]];perm(a,l+1);[a[l],a[i]]=[a[i],a[l]]}};perm([...values]);return out}
function signedPoints(base,filter=()=>true){const pts=[];for(const p of uniquePermutations(base)){for(let mask=0;mask<8;mask++){const q=p.map((n,i)=>n===0?0:n*((mask>>i)&1?-1:1));if(filter(q))pts.push(new THREE.Vector3(...q))}}const seen=new Map();pts.forEach(p=>seen.set(p.toArray().join(','),p));return [...seen.values()]}
function geometryFor(type){
  if(type==='cube')return new THREE.BoxGeometry(2.5,2.5,2.5);
  if(type==='tetra')return new THREE.TetrahedronGeometry(1.8,0);
  if(type==='octa')return new THREE.OctahedronGeometry(1.8,0);
  if(type==='dodeca')return new THREE.DodecahedronGeometry(1.75,0);
  if(type==='icosa')return new THREE.IcosahedronGeometry(1.82,0);
  if(type==='triPrism')return new THREE.CylinderGeometry(1.6,1.6,2.5,3,1,false);
  if(type==='hexPrism')return new THREE.CylinderGeometry(1.55,1.55,2.5,6,1,false);
  if(type==='cuboct')return new ConvexGeometry(signedPoints([1,1,0]));
  if(type==='truncOct')return new ConvexGeometry(signedPoints([0,1,2]));
  if(type==='truncCube')return new ConvexGeometry(signedPoints([1,1,1+Math.SQRT2]));
  return new THREE.IcosahedronGeometry(1.8,0);
}
function disposeGroup(){modelGroup.traverse(o=>{o.geometry?.dispose();if(o.material){(Array.isArray(o.material)?o.material:[o.material]).forEach(m=>m.dispose())}});scene.remove(modelGroup);modelGroup=new THREE.Group();scene.add(modelGroup)}
function buildModel(){
  disposeGroup(); const d=solids[currentKey],g=geometryFor(d.geometry); g.computeVertexNormals(); g.center();
  const mat=new THREE.MeshPhysicalMaterial({color:d.color,roughness:.32,metalness:.04,clearcoat:.35,clearcoatRoughness:.3,transparent:true,opacity:1,side:THREE.DoubleSide,flatShading:true});
  const mesh=new THREE.Mesh(g,mat);mesh.castShadow=true;mesh.receiveShadow=true;mesh.name='surface';modelGroup.add(mesh);
  const edgeMat=new THREE.LineBasicMaterial({color:0x252932,transparent:true,opacity:.72}); const edges=new THREE.LineSegments(new THREE.EdgesGeometry(g,18),edgeMat);edges.name='edges';modelGroup.add(edges);
  const pos=g.attributes.position; const unique=new Map(); for(let i=0;i<pos.count;i++){const v=new THREE.Vector3().fromBufferAttribute(pos,i);const k=v.toArray().map(n=>n.toFixed(3)).join(',');unique.set(k,v)}
  const dotGeo=new THREE.SphereGeometry(.065,12,8); const dotMat=new THREE.MeshBasicMaterial({color:0xc6ff4a}); const dots=new THREE.Group(); dots.name='dots'; for(const v of unique.values()){const dot=new THREE.Mesh(dotGeo,dotMat);dot.position.copy(v);dots.add(dot)} modelGroup.add(dots);
  const box=new THREE.Box3().setFromObject(modelGroup),size=box.getSize(new THREE.Vector3());const max=Math.max(size.x,size.y,size.z);modelGroup.userData.baseScale=3.5/max;modelGroup.scale.setScalar(modelGroup.userData.baseScale);modelGroup.rotation.set(.12,.35,0);updateViewMode();
}
function updateViewMode(){const s=modelGroup.getObjectByName('surface'),e=modelGroup.getObjectByName('edges'),v=modelGroup.getObjectByName('dots');if(!s)return;s.visible=viewMode!=='wire';s.material.opacity=viewMode==='xray'?.22:1;s.material.depthWrite=viewMode!=='xray';e.visible=true;e.material.opacity=viewMode==='xray'?1:viewMode==='wire'?1:.68;v.visible=viewMode==='vertices';}
function resize(){const wrap=$('#canvasWrap'),w=wrap.clientWidth,h=wrap.clientHeight;renderer.setSize(w,h,false);camera.aspect=w/h;camera.updateProjectionMatrix()}
new ResizeObserver(resize).observe($('#canvasWrap'));
function animate(t){requestAnimationFrame(animate);controls.update();if(!controls._domElementKeyEvents&&unfold<8&&!playing)modelGroup.rotation.y+=.0018;if(playing){unfold+=.45;if(unfold>=100){unfold=100;playing=false;$('#playUnfold').textContent='◀'}setUnfold(unfold)}renderer.render(scene,camera)}requestAnimationFrame(animate);

function renderCatalog(family){const list=$('#solidList');list.innerHTML='';const keys=familyOrder[family];$('#familyCount').textContent=`${keys.length} modelos`;keys.forEach(key=>{const d=solids[key],node=$('#solidCardTemplate').content.firstElementChild.cloneNode(true);node.dataset.key=key;node.querySelector('.solid-icon').textContent=d.glyph;node.querySelector('b').textContent=d.name;node.querySelector('small').textContent=`${d.faces} caras · ${d.edges} aristas`;node.classList.toggle('active',key===currentKey);node.addEventListener('click',()=>selectSolid(key));list.append(node)})}
function selectSolid(key){currentKey=key;const d=solids[key];if(!familyOrder[d.family].includes(key))return;$$('.family-tab').forEach(b=>{b.classList.toggle('active',b.dataset.family===d.family);b.setAttribute('aria-selected',b.dataset.family===d.family)});renderCatalog(d.family);$('#familyLabel').textContent=d.type.toUpperCase();$('#solidTitle').textContent=d.name;$('#infoName').textContent=d.full;$('#infoIntro').textContent=d.intro;$('#miniGlyph').textContent=d.glyph;$('#facesValue').textContent=$('#eqFaces').textContent=d.faces;$('#verticesValue').textContent=$('#eqVertices').textContent=d.vertices;$('#edgesValue').textContent=$('#eqEdges').textContent=d.edges;$('#faceType').textContent=d.face;$('#atVertex').textContent=d.atVertex;$('#dihedral').textContent=d.dihedral;$('#symmetry').textContent=d.symmetry;$('#areaFormula').textContent=d.area;$('#volumeFormula').textContent=d.volume;$('#workshopName').textContent=d.name.toLowerCase();setUnfold(0);buildModel();renderNet();showToast(`${d.name}: gira, acerca y abre su red`)}

function tri(x,y,s=48,flip=false,cls=''){const h=s*.866;return `<polygon class="${cls}" points="${x},${y+(flip?h:0)} ${x+s},${y+(flip?h:0)} ${x+s/2},${y+(flip?0:h)}"/>`}
function square(x,y,s=54,cls=''){return `<rect class="${cls}" x="${x}" y="${y}" width="${s}" height="${s}"/>`}
function polygonPoints(cx,cy,r,n,rot=-Math.PI/2){return Array.from({length:n},(_,i)=>`${cx+Math.cos(rot+i*Math.PI*2/n)*r},${cy+Math.sin(rot+i*Math.PI*2/n)*r}`).join(' ')}
function netMarkup(type){let m='';if(type==='cube'){[[130,105],[184,105],[238,105],[292,105],[184,51],[184,159]].forEach(p=>m+=square(...p));m+=`<polygon class="tab" points="130,105 118,116 118,147 130,159"/>`;}
  else if(type==='tri4'){m=tri(205,104,80)+tri(125,173,80,true)+tri(205,173,80,true)+tri(285,173,80,true)}
  else if(type==='tri8'){for(let i=0;i<4;i++){m+=tri(102+i*78,122,78,i%2===1);m+=tri(102+i*78,189,78,i%2===0)}}
  else if(type==='tri20'){for(let r=0;r<4;r++)for(let i=0;i<5;i++)m+=tri(62+i*78+(r%2?39:0),45+r*60,78,(i+r)%2===1)}
  else if(type==='pent12'){const centers=[[260,150],[260,70],[336,125],[307,214],[213,214],[184,125],[260,286],[384,204],[136,204],[384,56],[136,56],[260,-8]];centers.forEach(([x,y])=>m+=`<polygon points="${polygonPoints(x,y,47,5)}"/>`)}
  else if(type==='triPrism'){for(let i=0;i<3;i++)m+=`<rect x="${150+i*70}" y="105" width="70" height="105"/>`;m+=tri(150,44,70)+tri(290,210,70,true)}
  else if(type==='hexPrism'){for(let i=0;i<6;i++)m+=`<rect x="${50+i*70}" y="105" width="70" height="105"/>`;m+=`<polygon points="${polygonPoints(85,69,40,6)}"/><polygon points="${polygonPoints(365,246,40,6)}"/>`}
  else {for(let i=0;i<7;i++)m+=`<polygon points="${polygonPoints(80+i*60,150+(i%2?45:-5),34,i%3===0?4:6)}"/>`;}
  return m;
}
function renderNet(){const m=netMarkup(solids[currentKey].net);$('#netSvg').innerHTML=m;$('#workshopSvg').innerHTML=m}
function setUnfold(value){unfold=+value;$('#unfoldRange').value=unfold;$('#unfoldValue').textContent=`${Math.round(unfold)}%`;const p=unfold/100,e=Math.max(0,(p-.22)/.78);modelGroup.scale.setScalar((1-p*.28)*(modelGroup.userData.baseScale||1));modelGroup.rotation.x=.12+p*.52;modelGroup.position.y=p*.05;modelGroup.traverse(o=>{if(o.material&&o.name==='surface')o.material.opacity=(viewMode==='xray'?.22:1)*(1-e*.86)});const layer=$('#netLayer');layer.style.opacity=e;layer.style.transform=`scale(${.76+e*.24}) rotateX(${(1-e)*20}deg)`;if(p>.72)$('#canvasHint').textContent='Observa cómo las caras quedan conectadas por sus aristas';else $('#canvasHint').textContent='Arrastra · rueda para acercar · doble clic para centrar'}

$$('.family-tab').forEach(b=>b.addEventListener('click',()=>{const family=b.dataset.family;$$('.family-tab').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-selected',x===b)});currentKey=familyOrder[family][0];renderCatalog(family);selectSolid(currentKey)}));
$$('.tool-btn').forEach(b=>b.addEventListener('click',()=>{viewMode=b.dataset.view;$$('.tool-btn').forEach(x=>x.classList.toggle('active',x===b));updateViewMode()}));
